# Configuration for Deepgram Aura

To use this TTS service in bot.py, replace the TTS initialization with:

from pipecat.services.deepgram.tts import DeepgramTTSService

tts = DeepgramTTSService(
    api_key=os.getenv("API_KEY"),  # Use appropriate env var
    **{
    "voice": "aura-2-delia-en"
}
)

# Available voices: ['aura-2-delia-en', 'aura-2-asteria-en', 'aura-2-luna-en', 'aura-2-stella-en']
